void dei_ss_init( void )
{  	
    if(nvfs_rd_s( nvfs_sys_type , &ss_system_type, sizeof(ss_system_type) ) != NVFS_OK)
			ss_system_type = sys_type_assumed;

    dei_ss_trigger_enable =  !!((ss_system_type & SYS_TYPE_SS) == SYS_TYPE_SS );
            
 
	dei_ss_siren_low_batt_init();
	dei_ss_zone_bypass_init(); 
	dei_ss_trunk_release_init();	
	dei_ss_sys_arming_init();
	dei_ss_disarm_override_init();
	dei_ss_push_valet_init();
	dei_ss_push_trg_history_init();
	dei_ss_sensor_type_init();
	dei_ss_cmd_init();
	
	
	dei_ss_trigger_init();	
    dei_ss_logic_resume();	

	wake_register            ( (Wake_Func           )dei_ss_status_save );
    wdog_v_register_preamble ( (Wdog_v_Preamble_Func)dei_ss_status_save );
}

